{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.zouk_Daily_Summary_Report_Yesterday AS WITH params AS ( SELECT DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY) AS report_date ), Targets AS ( SELECT DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) AS Date, UPPER(t.Metrics) AS Channel, CAST(REPLACE(t.Target, \',\', \'\') AS FLOAT64) / (DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY) + 1) AS Daily_Target FROM `MapleMonk.Zouk_Targets` t, UNNEST(GENERATE_ARRAY(0, DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY))) AS n ), daily_targets AS ( SELECT Channel, ROUND(SUM(Daily_Target), 2) AS Target FROM Targets WHERE Date = (SELECT report_date FROM params) GROUP BY Channel ), primary_pandl AS ( SELECT UPPER(Marketplace_Segment) AS Channel, SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(return_gst, 0)) AS Net_Revenue, SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(return_gst, 0)) - SUM(IFNULL(CHANNEL_MARGIN, 0)) - SUM(IFNULL(cogs, 0)) + SUM(IFNULL(return_cogs, 0)) - SUM(IFNULL(offline_store_cost, 0)) - SUM(IFNULL(LOGISTICS_COST, 0)) + SUM(IFNULL(return_logistics_cost, 0)) - SUM(IFNULL(spend, 0)) - SUM(IFNULL(other_performance_spend, 0)) + SUM(IFNULL(brand_spend, 0)) AS CM, SAFE_DIVIDE( SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(return_gst, 0)) - SUM(IFNULL(CHANNEL_MARGIN, 0)) - SUM(IFNULL(cogs, 0)) + SUM(IFNULL(return_cogs, 0)) - SUM(IFNULL(offline_store_cost, 0)) - SUM(IFNULL(LOGISTICS_COST, 0)) + SUM(IFNULL(return_logistics_cost, 0)) - SUM(IFNULL(spend, 0)) - SUM(IFNULL(other_performance_spend, 0)) + SUM(IFNULL(brand_spend, 0)), SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(return_gst, 0)) ) * 100 AS CM_Percent FROM `MapleMonk.zouk_pandl` WHERE DATE = (SELECT report_date FROM params) GROUP BY 1 ), combined AS ( SELECT t.Channel, t.Target, ROUND(p.Net_Revenue / 10000000, 2) AS Achieved, ROUND(p.CM / 10000000, 2) AS CM, ROUND(p.CM_Percent, 2) AS CM_Percent FROM daily_targets t LEFT JOIN primary_pandl p USING (Channel) ), net_revenue_total AS ( SELECT \'NET REVENUE\' AS Channel, 0.61 AS Target, ROUND(SUM( IFNULL(BAU_MRP_SALES, 0) - IFNULL(return_mrp_sales, 0) - IFNULL(BAU_DISCOUNT, 0) - IFNULL(TRADE_MARGIN, 0) + IFNULL(return_trade_margin, 0) - IFNULL(Returns, 0) - IFNULL(gst, 0) + IFNULL(return_gst, 0) ) / 10000000, 2) AS Achieved, ROUND(SUM( IFNULL(BAU_MRP_SALES, 0) - IFNULL(return_mrp_sales, 0) - IFNULL(BAU_DISCOUNT, 0) - IFNULL(TRADE_MARGIN, 0) + IFNULL(return_trade_margin, 0) - IFNULL(Returns, 0) - IFNULL(gst, 0) + IFNULL(return_gst, 0) - IFNULL(CHANNEL_MARGIN, 0) - IFNULL(cogs, 0) + IFNULL(return_cogs, 0) - IFNULL(offline_store_cost, 0) - IFNULL(LOGISTICS_COST, 0) + IFNULL(return_logistics_cost, 0) - IFNULL(spend, 0) - IFNULL(other_performance_spend, 0) + IFNULL(brand_spend, 0) ) / 10000000, 2) AS CM, ROUND( SAFE_DIVIDE( SUM( IFNULL(BAU_MRP_SALES, 0) - IFNULL(return_mrp_sales, 0) - IFNULL(BAU_DISCOUNT, 0) - IFNULL(TRADE_MARGIN, 0) + IFNULL(return_trade_margin, 0) - IFNULL(Returns, 0) - IFNULL(gst, 0) + IFNULL(return_gst, 0) - IFNULL(CHANNEL_MARGIN, 0) - IFNULL(cogs, 0) + IFNULL(return_cogs, 0) - IFNULL(offline_store_cost, 0) - IFNULL(LOGISTICS_COST, 0) + IFNULL(return_logistics_cost, 0) - IFNULL(spend, 0) - IFNULL(other_performance_spend, 0) + IFNULL(brand_spend, 0) ), SUM( IFNULL(BAU_MRP_SALES, 0) - IFNULL(return_mrp_sales, 0) - IFNULL(BAU_DISCOUNT, 0) - IFNULL(TRADE_MARGIN, 0) + IFNULL(return_trade_margin, 0) - IFNULL(Returns, 0) - IFNULL(gst, 0) + IFNULL(return_gst, 0) ) ) * 100, 2 ) AS CM_Percent FROM `MapleMonk.zouk_pandl` p WHERE DATE = (SELECT report_date FROM params) ), secondary_total AS ( SELECT \'TOTAL SECONDARY NET REVENUE\' AS Channel, 0 AS Target, SUM(IFNULL(sales,0)) - SUM(IFNULL(secondary_Trade_Margin,0)) - SUM(IFNULL(Returns,0)) - SUM(IFNULL(gst,0)) + SUM(IFNULL(Secondary_TradeMargin_GST,0)) AS Achieved, 0 AS CM, SUM(IFNULL(brand_spend, 0)) - SUM(IFNULL(spend, 0)) - SUM(IFNULL(other_performance_spend, 0)) AS Perf_Spends, 0 AS CM_Percent FROM `MapleMonk.zouk_secondary_pandl` WHERE DATE = (SELECT report_date FROM params) ), perf_marketing AS ( SELECT \'TOTAL PERF. MARKETING %\' AS Channel, 0 AS Target, -1 * ROUND(SAFE_DIVIDE(SUM(Perf_Spends), SUM(Achieved)) * 100, 1) AS Achieved, NULL AS Achieved_Raw, 0 AS CM, 0 AS CM_Percent FROM secondary_total ), final_output AS ( SELECT * FROM net_revenue_total UNION ALL SELECT * FROM combined UNION ALL SELECT Channel, Target, ROUND(Achieved/10000000,2) AS Achieved, 0 AS CM, CM_Percent FROM secondary_total UNION ALL SELECT Channel, Target, Achieved, 0 AS CM, CM_Percent FROM perf_marketing ) SELECT Channel, Target, Achieved, CM, CM_Percent FROM final_output WHERE Achieved IS NOT NULL ORDER BY CASE Channel WHEN \'NET REVENUE\' THEN 1 WHEN \'D2C\' THEN 2 WHEN \'E-COMMERCE\' THEN 3 WHEN \'QUICK-COMMERCE\' THEN 4 WHEN \'OFFLINE\' THEN 5 WHEN \'TOTAL SECONDARY NET REVENUE\' THEN 6 WHEN \'TOTAL PERF. MARKETING %\' THEN 7 END ; CREATE OR REPLACE TABLE MapleMonk.zouk_Daily_Summary_Report_MTD AS WITH params AS ( SELECT DATE_TRUNC(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY), MONTH) AS month_start, DATE_ADD( DATE_TRUNC(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY), MONTH), INTERVAL 1 MONTH ) - 1 AS month_end, DATE_DIFF( DATE_ADD( DATE_TRUNC(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY), MONTH), INTERVAL 1 MONTH ) - 1, DATE_TRUNC(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY), MONTH), DAY ) + 1 AS total_days_in_month, DATE_DIFF( DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY), DATE_TRUNC(DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 1 DAY), MONTH), DAY ) + 1 AS days_passed ), Targets AS ( SELECT DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) AS Date, UPPER(t.Metrics) AS Channel, CAST(REPLACE(t.Target, \',\', \'\') AS FLOAT64) / (DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY) + 1) AS Daily_Target, CASE WHEN CURRENT_DATE(\'Asia/Kolkata\') > DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) THEN 0 ELSE DATE_DIFF(LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY)), CURRENT_DATE(\'Asia/Kolkata\'), DAY) + 1 END AS days_Remaining, EXTRACT(DAY FROM LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY))) AS no_of_days FROM `MapleMonk.Zouk_Targets` t, UNNEST(GENERATE_ARRAY(0, DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY))) AS n ), monthly_targets AS ( SELECT Channel, ROUND(SUM(Daily_Target), 2) AS Target FROM Targets WHERE EXTRACT(MONTH FROM Date) = EXTRACT(MONTH FROM CURRENT_DATE(\'Asia/Kolkata\')) GROUP BY Channel ), primary_pandl AS ( SELECT UPPER(Marketplace_Segment) AS Channel, SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(return_gst, 0)) AS Net_Revenue, SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(return_gst, 0)) - SUM(IFNULL(CHANNEL_MARGIN, 0)) - SUM(IFNULL(cogs, 0)) + SUM(IFNULL(return_cogs, 0)) - SUM(IFNULL(offline_store_cost, 0)) - SUM(IFNULL(LOGISTICS_COST, 0)) + SUM(IFNULL(return_logistics_cost, 0)) - SUM(IFNULL(spend, 0)) - SUM(IFNULL(other_performance_spend, 0)) + SUM(IFNULL(brand_spend, 0)) AS CM, SAFE_DIVIDE( SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(return_gst, 0)) - SUM(IFNULL(CHANNEL_MARGIN, 0)) - SUM(IFNULL(cogs, 0)) + SUM(IFNULL(return_cogs, 0)) - SUM(IFNULL(offline_store_cost, 0)) - SUM(IFNULL(LOGISTICS_COST, 0)) + SUM(IFNULL(return_logistics_cost, 0)) - SUM(IFNULL(spend, 0)) - SUM(IFNULL(other_performance_spend, 0)) + SUM(IFNULL(brand_spend, 0)), SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(return_gst, 0)) ) * 100 AS CM_Percent FROM `MapleMonk.zouk_pandl` WHERE DATE BETWEEN (SELECT month_start FROM params) AND (SELECT month_end FROM params) AND date < CURRENT_DATE(\'Asia/Kolkata\') GROUP BY 1 ), combined AS ( SELECT t.Channel, t.Target, ROUND(p.Net_Revenue / 10000000, 2) AS Achieved, ROUND(p.CM / 10000000, 2) AS CM, ROUND(p.CM_Percent, 1) AS CM_Percent FROM monthly_targets t LEFT JOIN primary_pandl p USING (Channel) ), net_revenue_total AS ( SELECT \'NET REVENUE\' AS Channel, SUM(Target) AS Target, ROUND(SUM(Achieved), 2) AS Achieved, ROUND(SUM(CM),2) AS CM, ROUND(SAFE_DIVIDE(SUM(Achieved * CM_Percent), SUM(Achieved)), 1) AS CM_Percent FROM combined WHERE Channel NOT IN (\'NET REVENUE\') ), secondary_total AS ( SELECT \'TOTAL SECONDARY NET REVENUE\' AS Channel, 0 AS Target, SUM(IFNULL(sales,0)) - SUM(IFNULL(secondary_Trade_Margin,0)) - SUM(IFNULL(Returns,0)) - SUM(IFNULL(gst,0)) + SUM(IFNULL(Secondary_TradeMargin_GST,0)) AS Achieved, ROUND( ( (SUM(IFNULL(sales,0)) - SUM(IFNULL(secondary_Trade_Margin,0)) - SUM(IFNULL(Returns,0)) - SUM(IFNULL(gst,0)) + SUM(IFNULL(Secondary_TradeMargin_GST,0))) / (SELECT days_passed FROM params) ) * (SELECT total_days_in_month FROM params) / 10000000, 2) AS Likely_Achieved, SUM(IFNULL(brand_spend, 0)) - SUM(IFNULL(spend, 0)) - SUM(IFNULL(other_performance_spend, 0)) AS Perf_Spends, 0 AS CM_Percent FROM `MapleMonk.zouk_secondary_pandl` WHERE DATE BETWEEN (SELECT month_start FROM params) AND (SELECT month_end FROM params) AND date < CURRENT_DATE(\'Asia/Kolkata\') ), perf_marketing AS ( SELECT \'TOTAL PERF. MARKETING %\' AS Channel, 0 AS Target, -1 * ROUND(SAFE_DIVIDE(SUM(Perf_Spends), SUM(Achieved)) * 100, 1) AS Achieved, 0 AS CM_Percent FROM secondary_total ), projection_base AS ( SELECT c.Channel, c.Target, c.Achieved, c.CM, c.CM_Percent, CASE WHEN c.Channel IN (\'D2C\', \'E-COMMERCE\', \'QUICK-COMMERCE\', \'OFFLINE\') THEN ROUND(c.Achieved / (SELECT days_passed FROM params) * (SELECT total_days_in_month FROM params), 2) ELSE NULL END AS Likely_Achieved, CASE WHEN c.Channel IN (\'D2C\', \'E-COMMERCE\', \'QUICK-COMMERCE\', \'OFFLINE\') THEN ROUND(c.CM / (SELECT days_passed FROM params) * (SELECT total_days_in_month FROM params), 2) ELSE NULL END AS CM_Predicted, CASE WHEN c.Channel IN (\'D2C\', \'E-COMMERCE\', \'QUICK-COMMERCE\', \'OFFLINE\') THEN ROUND(SAFE_DIVIDE( c.Achieved / (SELECT days_passed FROM params) * (SELECT total_days_in_month FROM params), c.Target ) * 100, 1) ELSE NULL END AS Percent_Achievement FROM combined c ), net_revenue_with_projection AS ( SELECT \'NET REVENUE\' AS Channel, SUM(Target) AS Target, ROUND(SUM(Achieved), 2) AS Achieved, ROUND(SUM(CM),2) AS CM, ROUND(SAFE_DIVIDE(SUM(Achieved * CM_Percent), SUM(Achieved)), 1) AS CM_Percent, ROUND(SUM(Likely_Achieved), 2) AS Likely_Achieved, ROUND(SUM(CM_Predicted), 2) AS CM_Predicted, ROUND(SAFE_DIVIDE(SUM(Likely_Achieved), SUM(Target)) * 100, 1) AS Percent_Achievement FROM projection_base WHERE Channel IN (\'D2C\', \'E-COMMERCE\', \'QUICK-COMMERCE\', \'OFFLINE\') ), final_output AS ( SELECT * FROM net_revenue_with_projection UNION ALL SELECT * FROM projection_base UNION ALL SELECT Channel, Target, ROUND(Achieved/10000000,2) AS Achieved, 0 as CM, CM_Percent, Likely_Achieved, 0 as CM_Predicted, NULL AS Percent_Achievement FROM secondary_total UNION ALL SELECT Channel, Target, Achieved, 0 as CM, CM_Percent, NULL AS Likely_Achieved, NULL as CM_Predicted, NULL AS Percent_Achievement FROM perf_marketing ) SELECT Channel, Target, Achieved, CM, CM_Percent, Likely_Achieved, Percent_Achievement, CM_Predicted FROM final_output WHERE Achieved IS NOT NULL ORDER BY CASE Channel WHEN \'NET REVENUE\' THEN 1 WHEN \'D2C\' THEN 2 WHEN \'E-COMMERCE\' THEN 3 WHEN \'QUICK-COMMERCE\' THEN 4 WHEN \'OFFLINE\' THEN 5 WHEN \'TOTAL SECONDARY NET REVENUE\' THEN 6 WHEN \'TOTAL PERF. MARKETING %\' THEN 7 END ; CREATE OR REPLACE TABLE MapleMonk.Zouk_Daily_Summary_Report_YTD AS WITH params AS ( SELECT DATE \'2025-04-01\' AS year_start, DATE \'2026-03-31\' AS year_end, DATE_DIFF(CURRENT_DATE(\'Asia/Kolkata\'), DATE \'2025-04-01\', DAY) AS days_passed ), targets AS ( SELECT \'NET REVENUE\' AS Channel, 245.00 AS Target UNION ALL SELECT \'D2C\', 100.00 UNION ALL SELECT \'E-COMMERCE\', 100.00 UNION ALL SELECT \'QUICK-COMMERCE\', 20.00 UNION ALL SELECT \'OFFLINE\', 25.00 ), primary_pandl AS ( SELECT UPPER(Marketplace_Segment) AS Channel, SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(return_gst, 0)) AS Net_Revenue, SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(return_gst, 0)) - SUM(IFNULL(CHANNEL_MARGIN, 0)) - SUM(IFNULL(cogs, 0)) + SUM(IFNULL(return_cogs, 0)) - SUM(IFNULL(offline_store_cost, 0)) - SUM(IFNULL(LOGISTICS_COST, 0)) + SUM(IFNULL(return_logistics_cost, 0)) - SUM(IFNULL(spend, 0)) - SUM(IFNULL(other_performance_spend, 0)) + SUM(IFNULL(brand_spend, 0)) AS CM, SAFE_DIVIDE( SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(return_gst, 0)) - SUM(IFNULL(CHANNEL_MARGIN, 0)) - SUM(IFNULL(cogs, 0)) + SUM(IFNULL(return_cogs, 0)) - SUM(IFNULL(offline_store_cost, 0)) - SUM(IFNULL(LOGISTICS_COST, 0)) + SUM(IFNULL(return_logistics_cost, 0)) - SUM(IFNULL(spend, 0)) - SUM(IFNULL(other_performance_spend, 0)) + SUM(IFNULL(brand_spend, 0)), SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(return_gst, 0)) ) * 100 AS CM_Percent FROM `MapleMonk.zouk_pandl` WHERE DATE BETWEEN (SELECT year_start FROM params) AND (SELECT year_end FROM params) AND DATE < CURRENT_DATE(\'Asia/Kolkata\') GROUP BY 1 ), combined AS ( SELECT t.Channel, t.Target, ROUND(p.Net_Revenue / 10000000, 2) AS Achieved, ROUND(p.CM / 10000000, 2) AS CM, ROUND(p.CM_Percent, 1) AS CM_Percent FROM targets t LEFT JOIN primary_pandl p USING (Channel) ), net_revenue_total AS ( SELECT \'NET REVENUE\' AS Channel, 245.00 AS Target, ROUND(SUM(Achieved), 2) AS Achieved, ROUND(SUM(CM),2) AS CM, ROUND(SAFE_DIVIDE(SUM(Achieved * CM_Percent), SUM(Achieved)), 1) AS CM_Percent FROM combined WHERE Channel IN (\'D2C\', \'E-COMMERCE\', \'QUICK-COMMERCE\', \'OFFLINE\') ), final AS ( SELECT c.Channel, c.Target, c.Achieved, c.CM, c.CM_Percent, ROUND( SAFE_DIVIDE(c.Achieved, (SELECT NULLIF(days_passed, 0) FROM params)) * 365, 2 ) AS Likely_Achieved, ROUND( SAFE_DIVIDE(c.CM, (SELECT NULLIF(days_passed, 0) FROM params)) * 365, 2 ) AS CM_Predicted, ROUND( SAFE_DIVIDE( SAFE_DIVIDE(c.Achieved, (SELECT NULLIF(days_passed, 0) FROM params)) * 365, NULLIF(c.Target, 0) ) * 100, 1 ) AS Percent_Achievement FROM combined c UNION ALL SELECT n.Channel, n.Target, n.Achieved, n.CM, n.CM_Percent, ROUND( SAFE_DIVIDE(n.Achieved, (SELECT NULLIF(days_passed, 0) FROM params)) * 365, 2 ) AS Likely_Achieved, ROUND( SAFE_DIVIDE(n.CM, (SELECT NULLIF(days_passed, 0) FROM params)) * 365, 2 ) AS CM_Predicted, ROUND( SAFE_DIVIDE( SAFE_DIVIDE(n.Achieved, (SELECT NULLIF(days_passed, 0) FROM params)) * 365, NULLIF(n.Target, 0) ) * 100, 1 ) AS Percent_Achievement FROM net_revenue_total n ) SELECT Channel, Target, Achieved, CM, CM_Percent, Likely_Achieved, CM_Predicted, Percent_Achievement FROM final where achieved is not null ORDER BY CASE Channel WHEN \'NET REVENUE\' THEN 1 WHEN \'D2C\' THEN 2 WHEN \'E-COMMERCE\' THEN 3 WHEN \'QUICK-COMMERCE\' THEN 4 WHEN \'OFFLINE\' THEN 5 END ;",
                    "transaction": true
